#!/usr/bin/env python3
"""Idempotently backfill ro-en (English target, Romanian source) lexemes.

Generated by scripts/derive_direction.py from scripts/backfill_lexemes_de_en.py
(levels a1, a2, b1).  Plumbing lives in scripts/_target_lexeme_backfill_common.py; this
file is data only.  The English classification is shared; every gloss below is
the Romanian meaning of the English token (it is the answer text of
multiple_choice and the prompt of translation exercises) and must never contain
the English answer word.

Run (after the ro-en course is imported), from backend/:

    docker compose run --rm -v "$(cd .. && pwd):/repo" -e PYTHONPATH=/repo/backend \
      --entrypoint python api /repo/scripts/backfill_lexemes_ro_en.py

Add --dry-run to classify without touching the database.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from _en_target_lexeme_common import (  # noqa: E402
    en_agreement_tags,
    en_token_display,
    normalize_en_token,
)
from _target_lexeme_backfill_common import classify, manifest_group, run  # noqa: E402

# The shared EN_POS only covers A1 and part of A2; nl-en's supplement
# (shared file wins) classifies the remaining A2/B1 tokens. Only the part of
# speech is taken from it; every Romanian gloss in this file is hand-written.
from backfill_lexemes_nl_en import EN_POS_ALL as EN_POS  # noqa: E402

LANG = "en"
LEVELS = {"a1": "ro-en", "a2": "ro-en-a2", "b1": "ro-en-b1", "b2": "ro-en-b2"}


def normalize(token: str) -> str:
    """Citation form: casefolded, sentence punctuation stripped, proper nouns
    keep their capital (the shared English convention)."""
    key = normalize_en_token(token)
    if key not in EN_POS:
        raise ValueError(f"missing English classification for {key!r} in EN_POS")
    return en_token_display(token, EN_POS[key])


def part_of_speech(token: str) -> str:
    return EN_POS[normalize_en_token(token)]


